function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value) &&
    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
}

function compileFeatureManifest(config) {
  if (!isPlainObject(config) || typeof config.label !== 'string' || config.label.length === 0 || !Array.isArray(config.flags)) {
    throw new TypeError('invalid manifest');
  }

  const keys = new Set();
  const flags = config.flags.map((flag) => {
    if (
      !isPlainObject(flag) ||
      typeof flag.key !== 'string' ||
      flag.key.length === 0 ||
      typeof flag.enabled !== 'boolean' ||
      !Number.isInteger(flag.rollout) ||
      flag.rollout < 0 ||
      flag.rollout >= 100
    ) {
      throw new TypeError('invalid flag');
    }
    if (keys.has(flag.key)) {
      throw new Error('duplicate flag key: ' + flag.key);
    }
    keys.add(flag.key);
    return { key: flag.key, enabled: flag.enabled, rollout: flag.rollout };
  });

  flags.sort((a, b) => a.key < b.key ? -1 : a.key > b.key ? 1 : 0);
  return 'module.exports = ' + JSON.stringify({ label: config.label, flags: flags }) + ';\n';
}

module.exports = compileFeatureManifest;

