'use strict';
const assert = require('node:assert');
const compileFeatureManifest = require('./solution');

assert.strictEqual(
  compileFeatureManifest({ label: 'empty', flags: [] }),
  'module.exports = {"label":"empty","flags":[]};\n'
);

const config = {
  label: 'release',
  flags: [
    { key: 'zeta', enabled: false, rollout: 100 },
    { key: 'alpha', enabled: true, rollout: 0 },
    { key: 'middle', enabled: true, rollout: 37 }
  ]
};
const snapshot = JSON.parse(JSON.stringify(config));
assert.strictEqual(
  compileFeatureManifest(config),
  'module.exports = {"label":"release","flags":[{"key":"alpha","enabled":true,"rollout":0},{"key":"middle","enabled":true,"rollout":37},{"key":"zeta","enabled":false,"rollout":100}]};\n'
);
assert.deepStrictEqual(config, snapshot);

const output = compileFeatureManifest(config);
config.label = 'changed';
config.flags[0].key = 'changed';
assert.ok(output.includes('"label":"release"'));
assert.ok(output.includes('"key":"zeta"'));

const invalid = [
  null,
  [],
  {},
  { label: '', flags: [] },
  { label: 2, flags: [] },
  { label: 'x', flags: {} },
  { label: 'x', flags: [null] },
  { label: 'x', flags: [{ key: '', enabled: true, rollout: 0 }] },
  { label: 'x', flags: [{ key: 'a', enabled: 1, rollout: 0 }] },
  { label: 'x', flags: [{ key: 'a', enabled: true, rollout: -1 }] },
  { label: 'x', flags: [{ key: 'a', enabled: true, rollout: 101 }] },
  { label: 'x', flags: [{ key: 'a', enabled: true, rollout: 1.5 }] }
];
for (const value of invalid) assert.throws(() => compileFeatureManifest(value), TypeError);
assert.throws(
  () => compileFeatureManifest({
    label: 'x',
    flags: [
      { key: 'same', enabled: true, rollout: 1 },
      { key: 'same', enabled: false, rollout: 2 }
    ]
  }),
  Error
);

